// План specs/job-dates.md 1.2 (кейс .qa/tests/job-dates/JDT-03). Admin, компания «test», десктоп, EN + HE. Только просмотр.
// Работа без даты — JOB-0082 (сохранена до исправления; наблюдение 18.10). Если ей поставят дату — заменить NOT_SCHEDULED_JOB.
import { test, expect } from '@playwright/test';
import {
  ADMIN_STATE, Lang, NOT_SCHEDULED_JOB, US_TZ, T, blockSmsSending, columnIndex, expectNoSmsSent, jobRow, openJobsList,
  restoreCompany, useLang,
} from './job-dates-helpers';

test.use({ storageState: ADMIN_STATE, timezoneId: US_TZ });

test.describe('Jobs list: job without a date (#664ccb)', () => {
  for (const lang of ['en', 'he'] as Lang[]) {
    test(`Jobs list (${lang.toUpperCase()}): a job without a date shows "${T[lang].notScheduled}" and no date / Today #664ccb @desktop @prod-safe`, async ({ page }) => {
      await useLang(page, lang);
      const smsHits = await blockSmsSending(page);
      try {
        await openJobsList(page);
        const row = jobRow(page, NOT_SCHEDULED_JOB);
        await expect(row, `${NOT_SCHEDULED_JOB} в списке`).toBeVisible();
        const idx = await columnIndex(page, T[lang].scheduled);
        const cell = row.locator('td, [role="cell"]').nth(idx);
        // Источник: комментарий программиста п.3 — «Not scheduled» / «לא נקבע תאריך» вместо даты создания и «Today».
        await expect(cell).toHaveText(new RegExp(`^\\s*${T[lang].notScheduled.replace(/ /g, '\\s+')}\\s*$`));
        await expect(cell).not.toContainText(lang === 'en' ? 'Today' : 'היום');
      } finally {
        await restoreCompany(page);
      }
      expectNoSmsSent(smsHits);
    });
  }
});
